const raw = $input.first().json.text || '';

let data;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  data = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { html: '<div style="font-family:sans-serif;padding:40px;text-align:center;"><h2 style="color:#ef4444;">Parsing Error</h2><p>AI response could not be parsed. Please try again.</p></div>' } }];
}

const score = Number(data.overall_score) || 0;
const verdictMap = {
  'STRONG BID': { bg: '#22c55e' },
  'MODERATE BID': { bg: '#f59e0b' },
  'WEAK BID': { bg: '#f97316' },
  'REJECT': { bg: '#ef4444' }
};
const vc = verdictMap[data.verdict] || { bg: '#6b7280' };

const criteria = [
  { key: 'understanding', label: 'Understanding of Client Needs' },
  { key: 'experience',    label: 'Relevant Experience & Proof'  },
  { key: 'approach',      label: 'Clarity of Approach'          },
  { key: 'pricing',       label: 'Pricing & Timeline'           },
  { key: 'communication', label: 'Communication Quality'        }
];

let scoreRows = '';
for (const c of criteria) {
  const s       = (data.scores && data.scores[c.key] && data.scores[c.key].score) || 0;
  const comment = (data.scores && data.scores[c.key] && data.scores[c.key].comment) || '';
  const barColor = s >= 16 ? '#22c55e' : s >= 12 ? '#f59e0b' : '#ef4444';
  const pct = ((s / 20) * 100).toFixed(0);
  scoreRows +=
    '<div style="margin-bottom:18px;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;">' +
        '<span style="font-size:13px;font-weight:600;color:#374151;">' + c.label + '</span>' +
        '<span style="font-size:13px;font-weight:700;color:' + barColor + ';">' + s + '/20</span>' +
      '</div>' +
      '<div style="background:#e5e7eb;border-radius:99px;height:7px;overflow:hidden;">' +
        '<div style="background:' + barColor + ';height:100%;width:' + pct + '%;border-radius:99px;"></div>' +
      '</div>' +
      '<div style="font-size:11px;color:#9ca3af;margin-top:3px;">' + comment + '</div>' +
    '</div>';
}

const li = function(arr) {
  return (arr || []).map(function(i) {
    return '<li style="margin-bottom:6px;line-height:1.5;color:#374151;">' + i + '</li>';
  }).join('');
};

const redFlagsHtml = (data.red_flags && data.red_flags.length > 0)
  ? '<div style="background:#fef2f2;border:1px solid #fecaca;border-radius:14px;padding:20px;margin-bottom:16px;">' +
      '<h3 style="margin:0 0 10px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#dc2626;font-weight:700;">Red Flags</h3>' +
      '<ul style="margin:0;padding-left:16px;">' + li(data.red_flags) + '</ul>' +
    '</div>'
  : '';

const html =
  '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;max-width:700px;margin:0 auto;padding:20px;">' +

    '<div style="background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);border-radius:20px;padding:36px;text-align:center;margin-bottom:20px;box-shadow:0 8px 32px rgba(102,126,234,0.35);">' +
      '<div style="font-size:80px;font-weight:900;color:white;line-height:1;">' + score + '</div>' +
      '<div style="font-size:16px;color:rgba(255,255,255,0.75);margin:2px 0 16px;">out of 100</div>' +
      '<div style="display:inline-flex;align-items:center;gap:8px;background:' + vc.bg + ';color:#fff;padding:9px 22px;border-radius:99px;font-size:14px;font-weight:700;">' + (data.verdict || '') + '</div>' +
      '<p style="margin:14px auto 0;font-size:13px;color:rgba(255,255,255,0.85);max-width:480px;line-height:1.5;">' + (data.verdict_reason || '') + '</p>' +
    '</div>' +

    '<div style="background:#f8f9ff;border:1px solid #e0e7ff;border-radius:16px;padding:22px;margin-bottom:16px;">' +
      '<h3 style="margin:0 0 18px;font-size:13px;text-transform:uppercase;letter-spacing:1.5px;color:#667eea;font-weight:700;">Score Breakdown</h3>' +
      scoreRows +
    '</div>' +

    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:16px;">' +
      '<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:14px;padding:18px;">' +
        '<h3 style="margin:0 0 10px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#15803d;font-weight:700;">Strengths</h3>' +
        '<ul style="margin:0;padding-left:16px;">' + li(data.strengths) + '</ul>' +
      '</div>' +
      '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:14px;padding:18px;">' +
        '<h3 style="margin:0 0 10px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#b45309;font-weight:700;">Weaknesses</h3>' +
        '<ul style="margin:0;padding-left:16px;">' + li(data.weaknesses) + '</ul>' +
      '</div>' +
    '</div>' +

    redFlagsHtml +

    '<div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:14px;padding:20px;margin-bottom:20px;">' +
      '<h3 style="margin:0 0 10px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#0369a1;font-weight:700;">How to Improve This Proposal</h3>' +
      '<ul style="margin:0;padding-left:16px;">' + li(data.improvements) + '</ul>' +
    '</div>' +

    '<div style="text-align:center;color:#d1d5db;font-size:11px;padding-top:16px;border-top:1px solid #f3f4f6;">Powered by n8n + OpenAI</div>' +
  '</div>';

return [{ json: { html } }];
